import hashlib as _hl, json as _js, datetime as _dt
_WEB_SECRET = "SemiTurnitin2025#WebXK9"

def _verify_web_code(code: str):
    try:
        p = _js.loads(_b64.b64decode(code.strip()).decode())
        n,e,s = p["n"],p["e"],p["s"]
        if _hl.sha256(f"{n}|{e}|{_WEB_SECRET}".encode()).hexdigest()[:16].upper()!=s:
            return False,"Invalid access code",0
        exp = _dt.datetime.strptime(e,"%Y%m%d")
        if _dt.datetime.now()>exp: return False,f"Expired on {exp.strftime('%Y-%m-%d')}",0
        return True,f"Welcome! {(exp-_dt.datetime.now()).days} days remaining",(exp-_dt.datetime.now()).days
    except: return False,"Invalid code format",0

def generate_web_code(name:str,days:int)->str:
    e=(_dt.datetime.now()+_dt.timedelta(days=days)).strftime("%Y%m%d")
    s=_hl.sha256(f"{name.upper().strip()}|{e}|{_WEB_SECRET}".encode()).hexdigest()[:16].upper()
    return _b64.b64encode(_js.dumps({"n":name.upper().strip(),"e":e,"s":s}).encode()).decode()

